      const legacyPage = parentReadStorageValue(PARENT_LEGACY_NOTIFICATIONS_ENABLED_KEY);
      const legacyPush = parentReadStorageValue(PARENT_LEGACY_WEB_PUSH_ENABLED_KEY);
      let enabled = false;
      if (legacyPage === "1" || legacyPush === "1") enabled = true;
      else if (legacyPage === "0" || legacyPush === "0") enabled = false;
      parentWriteStorageValue(PARENT_NOTIFICATION_ENABLED_KEY, enabled ? "1" : "0");
