      dragOverlay.addEventListener("mouseup", end, true);
      dragOverlay.addEventListener("touchmove", move, {capture: true, passive: false});
      dragOverlay.addEventListener("touchend", end, {capture: true, passive: false});
      dragOverlay.addEventListener("touchcancel", end, {capture: true, passive: false});
