      const presetNameInput = null;
      const presetSelect = modal.querySelector("#kwc-parent-preset-select");
      const presetSave = modal.querySelector("#kwc-parent-preset-save");
      const presetLoad = modal.querySelector("#kwc-parent-preset-load");
